-- Do not reset pending/uncertain provider campaigns or re-enroll historical contacts.
update public.newsletter_sequences
set steps='[{"subject":"Pas le temps de visiter ? Nous prenons le relais.","preheader":"Recherche, visites, candidatures : avancez sans bouleverser votre agenda.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Votre prochain logement mérite une place dans votre agenda. Pas toute la place.</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Recherche, visites, candidatures : avancez sans bouleverser votre agenda.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Votre prochain logement mérite une place dans votre agenda. Pas toute la place.</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-1\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/01-visites-deleguees.jpg\" width=\"568\" alt=\"Une agente réalise une visite à distance dans un appartement lumineux.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Entre le travail, les déplacements et les rendez-vous, trouver un appartement peut vite devenir un deuxième emploi. Et lorsqu’un logement vous plaît, vous n’êtes pas toujours disponible pour le visiter. Avec Logisorama, vous pouvez avancer sans porter seul toutes ces démarches.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-1\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">Vous choisissez les logements. Nous organisons la suite.</h2>\n<p style=\"margin:0 0 18px;\">Confiez votre recherche à un agent immobilier : nous sélectionnons des appartements selon vos critères, organisons les visites des biens qui vous intéressent et préparons vos postulations avec votre dossier. Vous gardez la main sur votre projet, avec un professionnel pour le faire avancer.</p>\n<p style=\"margin:0 0 18px;\">Moins d’allers-retours à gérer, plus de disponibilité pour prendre vos décisions. Une visite incompatible avec votre emploi du temps ne doit plus être le seul frein à votre candidature.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Recherche · Visites · Postulations : un accompagnement de A à Z.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Votre prochaine étape est simple : vérifiez vos critères, signez votre mandat et finalisez l’activation. Nous pourrons alors prendre le relais sur votre recherche.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-1\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"},{"subject":"Et si un agent de votre région cherchait pour vous ?","preheader":"Des critères précis, une sélection ciblée et un interlocuteur pour avancer.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Vous avez un projet. Donnez-lui un agent immobilier.</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Des critères précis, une sélection ciblée et un interlocuteur pour avancer.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Vous avez un projet. Donnez-lui un agent immobilier.</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-2\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/02-agent-regional.jpg\" width=\"568\" alt=\"Un agent étudie les quartiers et les logements d’une région de Suisse romande.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Ouvrir les annonces matin et soir ne suffit pas toujours à trouver le bon appartement. Il faut aussi comparer, vérifier les conditions et réagir lorsque le bien correspond à votre situation. Vous pouvez confier ce travail à un professionnel de votre région.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-2\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">Une recherche guidée par ce qui compte pour vous.</h2>\n<p style=\"margin:0 0 18px;\">Votre budget, les communes qui vous intéressent, le nombre de pièces et votre date d’emménagement deviennent les repères de notre recherche. Notre équipe sélectionne les possibilités pertinentes et vous accompagne pour passer de l’annonce à une candidature préparée.</p>\n<p style=\"margin:0 0 18px;\">Vous n’avez plus à tout suivre seul. Votre espace Logisorama reste accessible à toute heure pour consulter votre recherche, et votre agent vous accompagne dans les démarches et les choix à faire.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Un interlocuteur, vos critères et une recherche qui garde le cap.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Vous connaissez déjà vos priorités ? Faites-en le point de départ d’un accompagnement concret. Activez votre recherche pour confier votre projet à notre équipe.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-2\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"},{"subject":"Toujours sans réponse pour votre candidature ?","preheader":"Ne laissez pas une seule réponse en attente immobiliser toute votre recherche.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Vous avez postulé. Et maintenant, vous attendez ?</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Ne laissez pas une seule réponse en attente immobiliser toute votre recherche.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Vous avez postulé. Et maintenant, vous attendez ?</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-3\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/03-candidature.jpg\" width=\"568\" alt=\"Une agente transmet un dossier de candidature à un interlocuteur immobilier.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Vous avez visité un appartement, envoyé votre dossier, puis attendu un appel qui ne vient pas. Cette incertitude est fatigante, surtout lorsque votre date de déménagement approche. Vous n’êtes pas obligé de continuer seul ni de miser toute votre recherche sur une seule candidature.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-3\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">Laissez-nous prendre le relais.</h2>\n<p style=\"margin:0 0 18px;\">Nous vous aidons à réunir les pièces utiles, à préparer un dossier clair et à le transmettre à l’interlocuteur chargé du logement. En parallèle, nous poursuivons la recherche d’appartements adaptés à vos critères et organisons les prochaines démarches avec vous.</p>\n<p style=\"margin:0 0 18px;\">L’objectif est de faire avancer votre projet avec méthode : des logements sélectionnés, des visites organisées et des postulations préparées. La décision reste celle du bailleur ou de la gérance ; notre rôle est de vous accompagner sérieusement à chaque étape.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Votre dossier mérite une démarche suivie, pas seulement un email envoyé.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Transformez cette attente en prochaine étape. Activez votre recherche et donnez à notre équipe les moyens de travailler à vos côtés.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-3\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"},{"subject":"Recherche, visites, dossier : on s’occupe de la suite avec vous.","preheader":"Un seul accompagnement pour les démarches qui prennent le plus de temps.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Gardez votre énergie pour choisir votre futur chez-vous.</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Un seul accompagnement pour les démarches qui prennent le plus de temps.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Gardez votre énergie pour choisir votre futur chez-vous.</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-4\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/04-accompagnement.jpg\" width=\"568\" alt=\"Un dossier, un stylo et un logement illustrent les étapes d’un projet accompagné.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Chercher un logement, ce n’est pas seulement trouver une annonce. C’est aussi planifier les visites, rassembler les documents et suivre plusieurs candidatures à la fois. Avec Logisorama, ces étapes s’inscrivent dans un même accompagnement, avec un agent pour vous guider.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-4\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">De la première sélection à la postulation.</h2>\n<p style=\"margin:0 0 18px;\">Nous recherchons des appartements selon vos critères, vous aidons à sélectionner ceux qui vous plaisent, organisons les visites et préparons le dépôt de votre dossier. Vous connaissez la prochaine étape et pouvez vous concentrer sur les décisions qui vous concernent.</p>\n<p style=\"margin:0 0 18px;\">Vous restez au centre du projet : vos besoins, votre budget et vos choix orientent notre travail. Nous prenons en charge les démarches prévues au mandat pour vous apporter du temps, de la clarté et un suivi professionnel.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Vous décidez où vous souhaitez vivre. Nous vous aidons à y parvenir.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Votre espace est déjà le point de départ. Vérifiez vos informations et finalisez votre mandat pour passer de la recherche en solo à un accompagnement actif.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-4\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"},{"subject":"Votre déménagement approche ? Faisons avancer votre recherche.","preheader":"Une date à respecter mérite une recherche organisée dès maintenant.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Quand le temps compte, chaque démarche doit être utile.</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Une date à respecter mérite une recherche organisée dès maintenant.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Quand le temps compte, chaque démarche doit être utile.</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-5\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/05-recherche-urgente.jpg\" width=\"568\" alt=\"Une horloge, un carnet et des clés évoquent le calendrier d’une recherche de logement.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Une fin de bail, un nouvel emploi ou un changement de situation : lorsque votre recherche devient urgente, vous avez besoin de savoir quoi faire ensuite. Multiplier les annonces consultées ne suffit pas. Nous vous aidons à concentrer vos efforts sur les démarches qui font avancer votre projet.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-5\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">Un objectif de 15 à 45 jours, une méthode dès le départ.</h2>\n<p style=\"margin:0 0 18px;\">Nous construisons la recherche autour de votre date cible, de votre budget et des secteurs où vous pouvez vous installer. Une sélection ciblée, des visites organisées et un dossier préparé permettent de vous positionner lorsque des logements correspondent à vos critères.</p>\n<p style=\"margin:0 0 18px;\">Notre objectif est de vous aider à trouver en 15 à 45 jours. Il s’agit d’un objectif, pas d’un délai garanti : le résultat dépend notamment des biens disponibles, de vos critères et de la décision des bailleurs. Votre agent fait le point avec vous sur les priorités de votre recherche.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Plus tôt votre mandat est activé, plus tôt votre accompagnement peut commencer.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Indiquez votre échéance et finalisez votre activation maintenant. Vous donnerez à votre recherche un cadre concret, avec une équipe pour vous accompagner.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-5\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"},{"subject":"Pas de bail conclu grâce à nous, pas de commission.","preheader":"CHF 300 à l’activation, déduits en cas de succès. Remboursement sous conditions.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Votre commission, uniquement au succès.</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">CHF 300 à l’activation, déduits en cas de succès. Remboursement sous conditions.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"email-outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\"><tr><td><![endif]-->\n<table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"email-pad\" style=\"padding:24px 36px;border-bottom:1px solid #e7ebe5;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td><div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div><img src=\"https://logisorama.ch/email/logo-logisorama.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\"></td><td align=\"right\" class=\"email-brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.2px;color:#677a6c;\">VOTRE RECHERCHE DE LOCATION</td></tr></table></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:32px 36px 30px;font-size:16px;line-height:26px;color:#5c665e;overflow-wrap:anywhere;\">\n<h1 class=\"email-heading\" style=\"margin:0 0 22px;font:700 30px/36px Arial,Helvetica,sans-serif;letter-spacing:-.7px;color:#1c523c;\">Votre commission, uniquement au succès.</h1><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-6\"><img src=\"https://logisorama.ch/newsletter/candidats-2026-10/06-succes.jpg\" width=\"568\" alt=\"Une agente remet les clés d’un logement à un locataire.\" style=\"display:block;border:0;width:100%;height:auto;margin:0 0 26px;\"></a>\n<p style=\"margin:0 0 18px;\">Bonjour,</p><p style=\"margin:0 0 18px;\">Confier votre recherche est une décision importante. Vous devez savoir ce que vous payez et quand. Chez Logisorama, la commission est due uniquement lorsqu’un bail valable est conclu grâce à notre intervention. Un acompte de CHF 300 reste dû à l’activation, déduit en cas de succès et remboursable sous les conditions détaillées ci-dessous.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-6\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<h2 style=\"margin:28px 0 16px;font:700 24px/30px Arial,Helvetica,sans-serif;color:#193d2c;letter-spacing:-.4px;\">Un acompte pour démarrer. Des conditions claires.</h2>\n<p style=\"margin:0 0 18px;\">Un acompte de CHF 300 est dû pour activer votre recherche. Il est déduit de la commission en cas de succès. Cette commission correspond à un mois de loyer brut, avec un minimum de CHF 500 et la TVA uniquement si elle est due, conformément au mandat.</p>\n<p style=\"margin:0 0 18px;\">Sans bail conclu, vous pouvez demander le remboursement de l’acompte à l’échéance des 90 jours : la fin du mandat et la demande de remboursement doivent être notifiées entre le 75e et le 90e jour. Le remboursement intervient alors sous 30 jours après l’échéance. Sans cette démarche, le mandat se renouvelle ; en cas de résiliation anticipée de votre part, l’acompte reste acquis selon le contrat.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:24px 0;\"><tr><td style=\"padding:20px 22px;background:#f3f4ed;border-left:3px solid #205a43;font:700 17px/26px Arial,Helvetica,sans-serif;color:#205a43;\">Les conditions complètes sont présentées avant votre signature.</td></tr></table>\n<p style=\"margin:0 0 18px;\">Vous souhaitez avancer avec un professionnel et un cadre transparent ? Consultez votre mandat, posez-nous vos questions si nécessaire, puis activez votre recherche lorsque vous êtes prêt.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:24px 0;\"><tr><td bgcolor=\"#205a43\" style=\"border-radius:5px;mso-padding-alt:14px 22px;\"><a href=\"https://logisorama.ch/nouveau-mandat?utm_source=newsletter&amp;utm_medium=email&amp;utm_campaign=candidats-2026-10-13&amp;utm_content=etape-6\" style=\"display:inline-block;padding:14px 22px;border:1px solid #205a43;border-radius:5px;color:#ffffff;background:#205a43;font:700 16px/22px Arial,Helvetica,sans-serif;text-decoration:none;text-align:center;\">Activer ma recherche maintenant</a></td></tr></table>\n<p style=\"margin:0;font-size:14px;line-height:22px;color:#5c665e;\">Vous avez déjà un compte ? Utilisez la même adresse email et connectez-vous si nécessaire pour poursuivre votre démarche.</p></td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;background:#f3f4ed;border-top:1px solid #e7ebe5;font-size:13px;line-height:22px;color:#435b47;\"><strong>Au plaisir de vous accompagner,</strong><br>L’équipe Logisorama · Immo-rama<br>Recherche · Visites · Postulations</td></tr>\n<tr><td class=\"email-pad\" style=\"padding:22px 36px;font-size:12px;line-height:20px;color:#7b847a;\"><strong>Logisorama · Immo-rama</strong><br><a href=\"https://logisorama.ch\" style=\"color:#205a43;\">logisorama.ch</a> · <a href=\"mailto:support@logisorama.ch\" style=\"color:#205a43;\">support@logisorama.ch</a><div style=\"margin-top:12px;\">Immo-rama.ch · Chemin de l’Esparcette 5, 1023 Crissier<br>Visuels d’illustration.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#5c665e;text-decoration:underline;\">Se désinscrire</a></div></td></tr>\n</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>"}]'::jsonb, updated_at=now()
